mapper.select:
SELECT
    balance,
    observed_at
FROM account_balance_snapshot
WHERE financial_account_id = #{financialAccountId}
  AND observed_at >= #{startObservedAt}
  AND observed_at < #{endObservedAtExclusive}
ORDER BY observed_at ASC

SELECT tx.account_transaction_id, tx.occurred_at, tx.direction, tx.amount, tx.balance_after, tx.description, tx.counterparty_name, cfa.financial_account_id AS counterparty_account_id, cfa.bank_name AS counterparty_bank_name, cfa.account_name AS counterparty_account_name, cfa.account_number_ciphertext AS counterparty_account_number_ciphertext FROM account_transaction tx LEFT JOIN financial_account cfa ON cfa.financial_account_id = tx.counterparty_account_id WHERE tx.financial_account_id = #{financialAccountId}
AND ( tx.occurred_at < #{cursorOccurredAt} OR ( tx.occurred_at = #{cursorOccurredAt} AND tx.account_transaction_id < #{cursorTransactionId} ) )
ORDER BY tx.occurred_at DESC, tx.account_transaction_id DESC LIMIT #{limit}

SELECT COALESCE(SUM(amount), 0)
FROM account_transaction
WHERE financial_account_id = #{financialAccountId}
  AND direction = 'DEBIT'
  AND occurred_at >= #{startOccurredAt}
  AND occurred_at < #{endOccurredAtExclusive}
